import re
import json

# Read raw file  
with open('/workdir/data/books.json', 'r') as f:
    content = f.read()

# Find array start
books_match = re.search(r'"books"\s*:\s*\[', content)
if not books_match:
    print("Could not find books array")
    exit(1)

bracket_pos = content.find('[', books_match.start())

# Extract objects using brace matching
objects = []
i = bracket_pos
n = len(content)
while i < n:
    if content[i] == '{':
        depth = 0
        j = i
        while j < n:
            if content[j] == '{':
                depth += 1
            elif content[j] == '}':
                depth -= 1
                if depth == 0:
                    obj_str = content[i:j+1]
                    objects.append(obj_str)
                    i = j + 1
                    break
            j += 1
    else:
        i += 1

print(f"Found {len(objects)} objects")

# Parse each object with improved regex (handles single quotes)
books = []
for obj_str in objects:
    book = {}

    # Title - try double quote first, then single
    t1 = re.search(r'"title"\s*:\s*"([^"]*)"', obj_str)
    t2 = re.search(r'"title"\s*:\s*\'([^\']*)\'', obj_str)
    if t1:
        book['title'] = t1.group(1)
    elif t2:
        book['title'] = t2.group(1)
    else:
        book['title'] = None

    # Author
    a1 = re.search(r'"author"\s*:\s*"([^"]*)"', obj_str)
    a2 = re.search(r'"author"\s*:\s*\'([^\']*)\'', obj_str)
    if a1:
        book['author'] = a1.group(1)
    elif a2:
        book['author'] = a2.group(1)
    else:
        book['author'] = None

    # Year
    y = re.search(r'"year"\s*:\s*([^,}]+)', obj_str)
    if y:
        yval = y.group(1).strip().strip('"').strip("'")
        try:
            book['year'] = int(yval)
        except:
            book['year'] = yval

    # Genre
    g1 = re.search(r'"genre"\s*:\s*"([^"]*)"', obj_str)
    g2 = re.search(r'"genre"\s*:\s*\'([^\']*)\'', obj_str)
    if g1:
        book['genre'] = g1.group(1)
    elif g2:
        book['genre'] = g2.group(1)
    else:
        book['genre'] = None

    # Pages
    p1 = re.search(r'"pages"\s*:\s*([^,}]+)', obj_str)
    if p1:
        pval = p1.group(1).strip().strip('"').strip("'")
        try:
            book['pages'] = int(pval)
        except:
            book['pages'] = pval

    books.append(book)

print(f"Parsed {len(books)} books")

# Show problematic ones
for i, b in enumerate(books):
    if b['title'] is None or b['author'] is None or b['genre'] is None:
        print(f"Book {i}: {b}")

# Save
with open('/workdir/books_clean.json', 'w') as f:
    json.dump({"books": books}, f, indent=2)
print("Saved!")
